using System;using System.Collections.Generic;using System.Globalization;using System.Reflection;using System.Text;using System.Text.Json;using System.Data.SQLite;using OpenMetaverse;using OpenSim.Data;using OpenSim.Data.SQLite;
namespace log4net{public class Placeholder{}}
namespace OpenSim.Region.Framework.Interfaces{public class Placeholder{}}
namespace OpenSim.Framework{public static class DllmapConfigHelper{public static void RegisterAssembly(Assembly a){}}}
namespace OpenSim.Data{public class Migration{public Migration(SQLiteConnection c,Assembly a,string s){}public void Update(){}}}
public class TypedRow{public UUID PrincipalID;public bool Active;public int Count;public string Name;public Dictionary<string,string> Data;}
public class TypedTable:SQLiteGenericTableHandler<TypedRow>{public TypedTable():base("Data Source=:memory:","Records",""){}public TypedRow[] Raw(string sql){using var c=new SQLiteCommand(sql);return DoQuery(c);}}
class SqliteGenericReference {
 static string Hex(string s)=>s==null?"N":Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();
 static string Text(JsonElement x)=>x.ValueKind==JsonValueKind.Null?null:x.GetString()=="."?"":x.GetString();
 static string[] Strings(JsonElement x){if(x.ValueKind==JsonValueKind.Null)return null;var rows=new List<string>();foreach(var v in x.EnumerateArray())rows.Add(Text(v));return rows.ToArray();}
 static SQLiteConnection Reset<T>() where T:class,new(){var t=typeof(SQLiteGenericTableHandler<T>);var f=t.GetField("m_Connection",BindingFlags.Static|BindingFlags.NonPublic);((SQLiteConnection)f.GetValue(null))?.Close();f.SetValue(null,null);t.GetField("m_initialized",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,false);return null;}
 static SQLiteConnection Connection<T>() where T:class,new()=>(SQLiteConnection)typeof(SQLiteGenericTableHandler<T>).GetField("m_Connection",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);
 static void Exec(SQLiteConnection db,string sql){using var c=db.CreateCommand();c.CommandText=sql;c.ExecuteNonQuery();}
 static string Snapshot(SQLiteConnection db,string type){try{using var c=db.CreateCommand();c.CommandText=type=="friends"?"SELECT coalesce(group_concat(v,'|'),'') FROM (SELECT quote(PrincipalID)||':'||quote(Friend)||':'||quote(Flags)||':'||quote(Offered) AS v FROM Friends ORDER BY PrincipalID,Friend)":"SELECT coalesce(group_concat(v,'|'),'') FROM (SELECT quote(PrincipalID)||':'||quote(Active)||':'||quote(Count)||':'||quote(Name) AS v FROM Records ORDER BY PrincipalID,Name)";return Hex(Convert.ToString(c.ExecuteScalar(),CultureInfo.InvariantCulture));}catch{return "X";}}
 static string Data(Dictionary<string,string> d){string result="";foreach(var kv in d)result+=Hex(kv.Key)+"="+Hex(kv.Value)+",";return result;}
 static string Rows(FriendsData[] rows){string result=rows.Length+"|";foreach(var r in rows)result+=Hex(r.PrincipalID)+":"+Hex(r.Friend)+":"+Data(r.Data)+";";return result;}
 static string Rows(TypedRow[] rows){string result=rows.Length+"|";foreach(var r in rows)result+=r.PrincipalID+":"+(r.Active?"1":"0")+":"+r.Count+":"+Hex(r.Name)+":"+Data(r.Data)+";";return result;}
 static Dictionary<string,string> Fields(JsonElement x){if(x.ValueKind==JsonValueKind.Null)return null;var result=new Dictionary<string,string>();foreach(var pair in x.EnumerateArray())result[Text(pair[0])]=Text(pair[1]);return result;}
 static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var input=JsonDocument.Parse(Encoding.UTF8.GetString(Convert.FromHexString(line))).RootElement;string type=input.GetProperty("type").GetString();Reset<TypedRow>();Reset<FriendsData>();var typed=type=="typed"?new TypedTable():null;var friends=type=="friends"?new SQLiteFriendsData("Data Source=:memory:","Friends"):null;var db=type=="typed"?Connection<TypedRow>():Connection<FriendsData>();try{Exec(db,input.GetProperty("setup").GetString());}catch{Console.WriteLine("FIXTURE_EX");continue;}string output="";foreach(var op in input.GetProperty("ops").EnumerateArray()){string result="-";try{string kind=op.GetProperty("op").GetString();switch(kind){case "fields":result=type=="typed"?Rows(typed.Get(Strings(op.GetProperty("fields")),Strings(op.GetProperty("keys")))):Rows(friends.Get(Strings(op.GetProperty("fields")),Strings(op.GetProperty("keys"))));break;case "field":result=type=="typed"?Rows(typed.Get(Text(op.GetProperty("field")),Text(op.GetProperty("key")))):Rows(friends.Get(Text(op.GetProperty("field")),Text(op.GetProperty("key"))));break;case "where":result=type=="typed"?Rows(typed.Get(Text(op.GetProperty("where")))):Rows(friends.Get(Text(op.GetProperty("where"))));break;case "friends":result=Rows(friends.GetFriends(Text(op.GetProperty("principal"))));break;case "raw":Exec(db,op.GetProperty("sql").GetString());break;case "query":result=Rows(typed.Raw(op.GetProperty("sql").GetString()));break;case "delete":result=(type=="typed"?typed.Delete(Strings(op.GetProperty("fields")),Strings(op.GetProperty("keys"))):friends.Delete(Strings(op.GetProperty("fields")),Strings(op.GetProperty("keys"))))?"1":"0";break;case "singledelete":result=(type=="typed"?typed.Delete(Text(op.GetProperty("field")),Text(op.GetProperty("key"))):friends.Delete(Text(op.GetProperty("field")),Text(op.GetProperty("key"))))?"1":"0";break;case "store":if(type=="typed")result=typed.Store(op.GetProperty("nullrow").GetBoolean()?null:new TypedRow{PrincipalID=new UUID("00000000-0000-0000-0000-000000000001"),Active=true,Count=7,Name=Text(op.GetProperty("name")),Data=Fields(op.GetProperty("data"))})?"1":"0";else result=friends.Store(op.GetProperty("nullrow").GetBoolean()?null:new FriendsData{PrincipalID="a",Friend="b",Data=Fields(op.GetProperty("data"))})?"1":"0";break;}}catch{result="EX";}output+=Hex(result)+":"+Snapshot(db,type)+";";}Console.WriteLine(output);db.Close();}}
}
